(function(draw) {
    "use strict";
    draw.Plugin.add("filter");
    Object.assign(draw.Filter, {
        list: {},
        register(name, filterProcessor) {
            draw.Filter.list[name] = filterProcessor;
        },
        apply(filters, ui, bounds, currentCanvas, originCanvas, shape) {
            let item;
            filters.forEach(filter => {
                item = draw.Filter.list[filter.type];
                if (item) item.apply(filter, ui, bounds, currentCanvas, originCanvas, shape);
            });
        },
        getSpread(filters) {
            let item, width = 0;
            filters.forEach(filter => {
                item = draw.Filter.list[filter.type];
                if (item) width += item.getSpread(filter);
            });
            return width;
        }
    });
})(LeaferUI);
